# ------------------------------------------------------------------------------
# 05. HELPER: NORMALISE TEXT
# ------------------------------------------------------------------------------

normalise_text <- function(x) {
  
  y <- as.character(x)
  
  y <- iconv(
    y,
    from = "",
    to = "UTF-8",
    sub = ""
  )
  
  y[is.na(y)] <- ""
  
  y <- trimws(y)
  
  
  empty_selector <- (
    y == "" |
      toupper(y) == "NA" |
      toupper(y) == "NULL"
  )
  
  
  empty_selector[is.na(empty_selector)] <- FALSE
  
  
  y[empty_selector] <- NA_character_
  
  
  y
}


# ------------------------------------------------------------------------------
# 06. HELPER: NORMALISE MATCH KEY
# ------------------------------------------------------------------------------

normalise_key <- function(x) {
  
  y <- normalise_text(x)
  
  y <- tolower(y)
  
  y <- gsub(
    "[[:space:]]+",
    " ",
    y
  )
  
  y <- trimws(y)
  
  y
}


# ------------------------------------------------------------------------------
# 07. HELPER: SAFE CSV READ
# ------------------------------------------------------------------------------

safe_read_csv <- function(path) {
  
  if (!file.exists(path)) {
    
    stop(
      paste0(
        "Required file not found:\n",
        path
      )
    )
  }
  
  
  attempts <- list(
    
    function() {
      
      read.csv(
        path,
        stringsAsFactors = FALSE,
        check.names = FALSE,
        fileEncoding = "UTF-8"
      )
    },
    
    function() {
      
      read.csv(
        path,
        stringsAsFactors = FALSE,
        check.names = FALSE,
        fileEncoding = "UTF-8-BOM"
      )
    },
    
    function() {
      
      read.csv(
        path,
        stringsAsFactors = FALSE,
        check.names = FALSE,
        fileEncoding = "latin1"
      )
    }
  )
  
  
  errors <- character(0)
  
  
  for (attempt_index in seq_along(attempts)) {
    
    result <- tryCatch(
      
      attempts[[attempt_index]](),
      
      error = function(e) {
        
        errors <<- c(
          errors,
          conditionMessage(e)
        )
        
        NULL
      }
    )
    
    
    if (!is.null(result)) {
      
      return(result)
    }
  }
  
  
  stop(
    paste0(
      "Unable to read CSV:\n",
      path,
      "\n\nErrors:\n",
      paste(
        errors,
        collapse = "\n"
      )
    )
  )
}


# ------------------------------------------------------------------------------
# 08. HELPER: FIND PUBLISHED RECOGNISED-TAXON TABLE
# ------------------------------------------------------------------------------

find_recognised_taxon_file <- function(root) {
  
  if (!dir.exists(root)) {
    
    stop(
      paste0(
        "Published VPJD root not found:\n",
        root
      )
    )
  }
  
  
  candidate_files <- list.files(
    root,
    pattern = "\\.csv$",
    recursive = TRUE,
    full.names = TRUE,
    ignore.case = TRUE
  )
  
  
  exact_selector <- (
    tolower(
      basename(candidate_files)
    ) ==
      "vpjd_recognised_taxa.csv"
  )
  
  
  exact_matches <- candidate_files[
    exact_selector
  ]
  
  
  if (length(exact_matches) == 0L) {
    
    stop(
      paste0(
        "Canonical recognised-taxon table not found under:\n",
        root,
        "\n\nExpected filename:\n",
        "vpjd_recognised_taxa.csv"
      )
    )
  }
  
  
  if (length(exact_matches) > 1L) {
    
    file_sizes <- file.info(
      exact_matches
    )$size
    
    
    exact_matches <- exact_matches[
      order(
        file_sizes,
        decreasing = TRUE
      )
    ]
  }
  
  
  exact_matches[1L]
}


# ------------------------------------------------------------------------------
# 09. HELPER: SHA-256
#
# Uses digest if available.
#
# Validation does NOT fail merely because digest is unavailable.
# ------------------------------------------------------------------------------

calculate_sha256 <- function(path) {
  
  if (!requireNamespace(
    "digest",
    quietly = TRUE
  )) {
    
    return(NA_character_)
  }
  
  
  digest::digest(
    file = path,
    algo = "sha256",
    serialize = FALSE
  )
}


