    distribution_relationship_key,
  
  in_evidence =
    all_relationship_keys %in%
    evidence_relationship_key,
  
  stringsAsFactors = FALSE
)


relationship_comparison$agreement <- (
  relationship_comparison$in_distribution ==
    relationship_comparison$in_evidence
)


